/* Generated by Trae Work */
/* 全站悬浮 AI 助手：内嵌豆包网页（官方未强制禁止 iframe）；可收缩为气泡、可拖动、可全屏；含备考提问词 */
"use strict";
(function () {
  const DOUBAO_URL = "https://www.doubao.com/chat/";
  const PROMPTS = [
    { label: "① 出题测验", text: "我是自考计算机（080901）+ 28 考研（数二/英二/408）考生。请就我下一条消息发你的知识点，出 5 道测试题，等我作答后逐题讲解并指出易错点。" },
    { label: "② 零基础讲解", text: "请用大白话讲解下面这个概念，把我当成完全零基础的学生，多打生活比方，最后给一个带完整步骤的小例子：" },
    { label: "③ 错题诊断", text: "下面是我的错题和当时的错误思路，请指出错因、给出正确解法，再出 2 道同类题让我巩固：" }
  ];

  function init() {
    if (document.getElementById("aif-root")) return;

    const root = document.createElement("div");
    root.id = "aif-root";
    root.innerHTML = `
      <button id="aif-bubble" title="AI 助手（豆包）">AI</button>
      <div id="aif-panel" style="display:none;">
        <div id="aif-head">
          <span id="aif-title">AI 助手 · 豆包</span>
          <span id="aif-head-btns">
            <span id="aif-prompt-toggle" title="备考提问词（点击复制）">提问词 ▾</span>
            <span id="aif-menu" title="全屏 / 还原"><button class="aif-ib" id="aif-full">⛶</button></span>
            <span><button class="aif-ib" id="aif-close" title="收起">—</button></span>
          </span>
        </div>
        <div id="aif-prompts">${PROMPTS.map((p, i) => `<button class="aif-prompt" data-i="${i}">${p.label}</button>`).join("")}</div>
        <div id="aif-body"></div>
        <div id="aif-toast"></div>
      </div>`;
    document.body.appendChild(root);

    const bubble = document.getElementById("aif-bubble");
    const panel = document.getElementById("aif-panel");
    const body = document.getElementById("aif-body");
    const head = document.getElementById("aif-head");
    const fullBtn = document.getElementById("aif-full");
    const closeBtn = document.getElementById("aif-close");
    const promptToggle = document.getElementById("aif-prompt-toggle");
    const promptBox = document.getElementById("aif-prompts");
    const toast = document.getElementById("aif-toast");
    let loaded = false, full = false;

    function showToast(msg) {
      toast.textContent = msg;
      toast.style.display = "block";
      clearTimeout(showToast._t);
      showToast._t = setTimeout(() => { toast.style.display = "none"; }, 2600);
    }
    function open() {
      panel.style.display = "flex";
      bubble.style.display = "none";
      if (!loaded) {
        const f = document.createElement("iframe");
        f.src = DOUBAO_URL;
        f.allow = "clipboard-write; microphone";
        f.title = "豆包";
        body.appendChild(f);
        loaded = true;
      }
      Store.set("aif_open", true);
    }
    function collapse() {
      panel.style.display = "none";
      bubble.style.display = "flex";
      Store.set("aif_open", false);
    }
    function setFull(v) {
      full = v;
      panel.classList.toggle("aif-full", v);
      fullBtn.textContent = v ? "❐" : "⛶";
      fullBtn.title = v ? "还原窗口" : "全屏";
    }
    bubble.addEventListener("click", open);
    closeBtn.addEventListener("click", collapse);
    fullBtn.addEventListener("click", () => setFull(!full));
    promptToggle.addEventListener("click", () => promptBox.classList.toggle("show"));
    document.addEventListener("click", e => {
      if (!promptBox.contains(e.target) && e.target !== promptToggle) promptBox.classList.remove("show");
    });
    promptBox.querySelectorAll(".aif-prompt").forEach(btn => {
      btn.addEventListener("click", async () => {
        const p = PROMPTS[Number(btn.dataset.i)];
        let ok = true;
        try { await navigator.clipboard.writeText(p.text); } catch (err) { ok = false; }
        promptBox.classList.remove("show");
        showToast(ok ? "提问词已复制 —— 点进豆包输入框 Ctrl+V 粘贴发送" : "无法自动复制，请手动输入提问词");
      });
    });

    /* 拖动（仅非全屏时，按住标题栏） */
    let dragging = null;
    head.addEventListener("pointerdown", e => {
      if (full || e.target.closest(".aif-ib") || e.target.id === "aif-prompt-toggle") return;
      const r = panel.getBoundingClientRect();
      dragging = { dx: e.clientX - r.left, dy: e.clientY - r.top };
      head.setPointerCapture(e.pointerId);
    });
    head.addEventListener("pointermove", e => {
      if (!dragging) return;
      const w = panel.offsetWidth, hgt = panel.offsetHeight;
      let x = Math.min(Math.max(0, e.clientX - dragging.dx), innerWidth - w);
      let y = Math.min(Math.max(0, e.clientY - dragging.dy), innerHeight - hgt);
      panel.style.left = x + "px";
      panel.style.top = y + "px";
      panel.style.right = "auto";
      panel.style.bottom = "auto";
    });
    head.addEventListener("pointerup", () => { dragging = null; });

    /* 恢复上次状态 */
    if (Store.get("aif_open", false)) open();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
